CREATE DATABASE IF NOT EXISTS findback CHARACTER SET utf8mb4; USE findback;
CREATE TABLE pengguna(id INT AUTO_INCREMENT PRIMARY KEY,nama VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,no_hp VARCHAR(20) NULL,kata_sandi_hash VARCHAR(255) NOT NULL,peran ENUM('pengguna','admin') DEFAULT 'pengguna',aktif TINYINT(1) DEFAULT 1,dibuat_pada DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE kategori(id INT AUTO_INCREMENT PRIMARY KEY,nama VARCHAR(50) UNIQUE,urutan INT);
INSERT INTO kategori(nama,urutan) VALUES('Botol minum',1),('KTM',2),('Handphone',3),('Kunci',4),('Charger/Powerbank',5),('Alat tulis/Buku',6),('Laptop',7),('Tas',8),('Pakaian',9),('Aksesoris',10),('Lainnya',99);
CREATE TABLE laporan(id INT AUTO_INCREMENT PRIMARY KEY,pengguna_id INT NOT NULL,jenis ENUM('hilang','temuan') NOT NULL,kategori_id INT NOT NULL,judul VARCHAR(150) NOT NULL,deskripsi TEXT,tanggal_kejadian DATE,lokasi_cerita TEXT,ciri_rahasia VARCHAR(255) NULL,posisi_barang ENUM('dipegang_penemu','kemahasiswaan','staf_satpam') NULL,kondisi_titipan TEXT NULL,reward VARCHAR(150) NULL,status ENUM('menunggu_persetujuan','hilang','ditemukan','dalam_klaim','dikembalikan','ditutup','ditolak','dicabut') NOT NULL,foto_url VARCHAR(255) NULL,status_sebelum VARCHAR(20) NULL,ktm TINYINT(1) DEFAULT 0,dibuat_pada DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(pengguna_id) REFERENCES pengguna(id),FOREIGN KEY(kategori_id) REFERENCES kategori(id),INDEX(status),INDEX(pengguna_id,status),FULLTEXT(judul,deskripsi,lokasi_cerita));
CREATE TABLE klaim(id INT AUTO_INCREMENT PRIMARY KEY,laporan_temuan_id INT NOT NULL,pengklaim_id INT NOT NULL,status ENUM('chat','dipilih','ditolak','ditutup','selesai','dibatalkan') DEFAULT 'chat',laporan_hilang_id INT NULL,ditutup_oleh_klaim_id INT NULL,foto_bukti VARCHAR(255) NULL,dibuat_pada DATETIME DEFAULT CURRENT_TIMESTAMP,dipilih_unik INT AS (IF(status='dipilih',laporan_temuan_id,NULL)) VIRTUAL,UNIQUE(dipilih_unik),UNIQUE(laporan_temuan_id,pengklaim_id),FOREIGN KEY(laporan_temuan_id) REFERENCES laporan(id),FOREIGN KEY(pengklaim_id) REFERENCES pengguna(id));
CREATE TABLE pesan(id INT AUTO_INCREMENT PRIMARY KEY,klaim_id INT NOT NULL,pengirim_id INT NOT NULL,isi TEXT NOT NULL,disembunyikan TINYINT(1) DEFAULT 0,dikirim_pada DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(klaim_id) REFERENCES klaim(id) ON DELETE CASCADE,INDEX(klaim_id,id));
CREATE TABLE riwayat_poin(id INT AUTO_INCREMENT PRIMARY KEY,pengguna_id INT NOT NULL,laporan_id INT NULL,jumlah INT NOT NULL,alasan VARCHAR(100),dibuat_pada DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE(pengguna_id,laporan_id,alasan));
CREATE TABLE notifikasi(id INT AUTO_INCREMENT PRIMARY KEY,pengguna_id INT NOT NULL,isi VARCHAR(255),tautan VARCHAR(255) NULL,sudah_dibaca TINYINT(1) DEFAULT 0,dibuat_pada DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX(pengguna_id,sudah_dibaca));
CREATE TABLE aduan(id INT AUTO_INCREMENT PRIMARY KEY,pelapor_id INT NOT NULL,jenis ENUM('laporan','pesan') NOT NULL,target_id VARCHAR(30) NOT NULL,alasan VARCHAR(100),keterangan VARCHAR(255),status ENUM('baru','diproses','selesai') DEFAULT 'baru',penangan_id INT NULL,diambil_pada DATETIME NULL,keputusan VARCHAR(30) NULL,catatan TEXT NULL,dibuat_pada DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE(pelapor_id,jenis,target_id));
CREATE TABLE peringatan(id INT AUTO_INCREMENT PRIMARY KEY,pengguna_id INT NOT NULL,aduan_id INT NULL,alasan VARCHAR(100),dibuat_pada DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE log_admin(id INT AUTO_INCREMENT PRIMARY KEY,admin_id INT NOT NULL,teks VARCHAR(255),dibuat_pada DATETIME DEFAULT CURRENT_TIMESTAMP);
